// Form data extract karo
const masterSheetId = $input.first().json['Master Google Sheet ID'] || '';
const city = $input.first().json['City / State'] || '';
const country = $input.first().json['Country'] || '';
const niche = $input.first().json['Niche / Industry'] || '';
const customQuestions = $input.first().json['Custom Questions / Query Guidelines'] || '';
const sourcesChoice = $input.first().json['Sources to Search'] || 'All Platforms (24h Filter)';

// Tab Name build karo (e.g., Real Estate - Houston)
const tabName = `${niche} - ${city}`.slice(0, 30); // Max 30 chars for tab safety

// Reddit search query build karo (24 Hours filter: t=day, sort=new)
const searchQuery = `${niche} ${city} ${country}`;
const redditQuery = encodeURIComponent(searchQuery);
const redditUrl = `https://www.reddit.com/search.json?q=${redditQuery}&sort=new&t=day&limit=25&type=link`;

// 24h Filtered Search URLs for other platforms (using Google tbs=qdr:d parameter -> past 24 hours)
const linkedin24hUrl = `https://www.google.com/search?q=site:linkedin.com/posts+${encodeURIComponent(`${niche} ${city} ${country}`)}&tbs=qdr:d`;
const reddit24hWebUrl = `https://www.reddit.com/search/?q=${encodeURIComponent(`${niche} ${city} ${country}`)}&t=day&sort=new`;
const googleMapsUrl = `https://www.google.com/maps/search/${encodeURIComponent(`${niche} ${city} ${country}`)}`;
const facebook24hUrl = `https://www.google.com/search?q=site:facebook.com+${encodeURIComponent(`${niche} ${city}`)}&tbs=qdr:d`;
const generalForums24hUrl = `https://www.google.com/search?q=${encodeURIComponent(`"${niche}" "${city}" ("help" OR "question" OR "looking for" OR "recommendation")`)}&tbs=qdr:d`;

// Custom questions parse karo
const questionsList = customQuestions
  .split('\n')
  .map(q => q.trim())
  .filter(q => q.length > 0);

// Timestamp
const timestamp = new Date().toISOString();

return [
  {
    json: {
      masterSheetId,
      tabName,
      city,
      country,
      niche,
      customQuestions: questionsList,
      customQuestionsRaw: customQuestions,
      sourcesChoice,
      redditUrl,
      redditQuery: searchQuery,
      linkedin24hUrl,
      reddit24hWebUrl,
      googleMapsUrl,
      facebook24hUrl,
      generalForums24hUrl,
      timestamp
    }
  }
];

// Reddit response parse karo
const redditData = $input.first().json;
const posts = redditData?.data?.children || [];

// Previous node ka data lo
const prevData = $('Build Search Data').first().json;

// Strictly 24 hours (86400 seconds) timestamp filter
const nowInSeconds = Math.floor(Date.now() / 1000);
const twentyFourHoursAgo = nowInSeconds - 86400;

// Filter posts posted within the last 24 hours
const recentPosts = posts.filter(post => {
  const createdUtc = post.data?.created_utc || 0;
  return createdUtc >= twentyFourHoursAgo;
});

// Fallback: If exact 24h filter returns 0 (e.g. slow subreddit), take top retrieved by t=day API
const finalPosts = recentPosts.length > 0 ? recentPosts : posts.slice(0, 10);

// Reddit posts format karo
const formattedPosts = finalPosts.map((post, index) => {
  const p = post.data;
  const postDate = new Date(p.created_utc * 1000);
  const hoursAgo = Math.max(0, Math.round((Date.now() - postDate.getTime()) / (1000 * 60 * 60)));

  return {
    index: index + 1,
    title: p.title || '',
    subreddit: p.subreddit_name_prefixed || '',
    url: p.permalink ? `https://reddit.com${p.permalink}` : '',
    score: p.score || 0,
    numComments: p.num_comments || 0,
    author: p.author || '',
    postedTime: `${hoursAgo} hours ago`
  };
});

// Summary for sheets
const topPostsSummary = formattedPosts.length > 0
  ? formattedPosts.slice(0, 10)
      .map(p => `${p.index}. [${p.postedTime}] ${p.title} (${p.subreddit})
   URL: ${p.url}`)
      .join('\n\n')
  : 'No posts/queries found in the last 24 hours for this location & niche.';

// Custom questions as string
const questionsStr = prevData.customQuestions.length > 0
  ? prevData.customQuestions.map((q, i) => `Q${i+1}: ${q}`).join('\n')
  : 'No custom questions provided';

return [
  {
    json: {
      MasterSheetId: prevData.masterSheetId,
      TabName: prevData.tabName,
      Timestamp: prevData.timestamp,
      City: prevData.city,
      Country: prevData.country,
      Niche: prevData.niche,
      'Sources Selected': prevData.sourcesChoice,
      'Custom Questions': questionsStr,
      '24h Queries Found': formattedPosts.length,
      'Top Reddit Queries (Last 24h)': topPostsSummary,
      'Reddit (24h Search)': prevData.reddit24hWebUrl,
      'LinkedIn (24h Search)': prevData.linkedin24hUrl,
      'Facebook (24h Search)': prevData.facebook24hUrl,
      'General Forums (24h Search)': prevData.generalForums24hUrl,
      'Google Maps URL': prevData.googleMapsUrl,
      _allPosts: JSON.stringify(formattedPosts)
    }
  }
];
